def first_short_change(notes):
    fives = tens = 0
    for i, note in enumerate(notes):
        if note == 5:
            fives += 1
        elif note == 10:
            if fives == 0:
                return i
            fives -= 1
            tens += 1
        elif tens and fives:
            tens -= 1
            fives -= 1
        elif fives >= 3:
            fives -= 3
        else:
            return i
    return -1
